/* ===================== BÀI 5 · Điện áp, dòng và mức logic ===================== */
/* ---- công cụ tương tác của bài: chép từ tools/author/nentang/w05.js bởi m02lib.write2 ---- */
/* Bài 5 · Máy tính điện trở LED và mức logic (AMTS-FND-002-SIM05 LED/Resistor Signal, bản cho Bài 5).
   NTE5: phần TÍNH (engine), hàm thuần, không đụng DOM; kiểm thử: node tests/nentang/test_m02.js (so với Python độc lập).
   makeNtLedCalc: phần VẼ, chỉ đọc ô nhập, gọi NTE5 và hiện kết quả. Mọi thông số mặc định là GIẢ ĐỊNH của bài,
   không phải số của một chip cụ thể: học viên phải thay bằng số trong datasheet của đúng linh kiện. */
const NTE5={
  E12:[10,12,15,18,22,27,33,39,47,56,68,82],
  /* đọc số thập phân kiểu Việt hoặc kiểu Anh: "4,7" = "4.7"; dấu trừ "−" (U+2212) = "-"; trả NaN nếu không đọc được */
  num(s){s=String(s==null?"":s).trim().replace(",",".").replace("\u2212","-");return/^[-+]?(\d+\.?\d*|\.\d+)$/.test(s)?Number(s):NaN},
  /* giá trị chuẩn dãy E12 gần nhất: dir=1 lấy giá trị nhỏ nhất ≥ r (điện trở hạn dòng LED), dir=-1 lấy giá trị lớn nhất ≤ r */
  e12(r,dir){if(!(r>0)||!isFinite(r))return NaN;let best=NaN;
    for(let k=-1;k<=7;k++)for(const m of NTE5.E12){const v=Number((m*Math.pow(10,k)).toPrecision(12));
      if(dir>0&&v>=r*(1-1e-9)&&!(v>=best))best=v;
      if(dir<0&&v<=r*(1+1e-9)&&!(v<=best))best=v}
    return best},
  /* điện trở hạn dòng LED. mode "low": nguồn Vs → R → LED → chân ở mức 0 (sụt VOL); "high": chân mức 1 (VOH) → R → LED → GND.
     c = {mode, vs, vf, vol, voh, i (mA), n (số LED cùng cổng), pin (mA), port (mA), ioh (µA)}.
     ioh = I_OH, ĐIỀU KIỆN ĐO của V_OH trong bảng DC (dấu trừ = dòng chảy ra khỏi chân), KHÔNG phải dòng cấp lớn nhất của chân:
     bảng chỉ bảo đảm V_OH ở dòng cấp đó; dòng cấp lớn hơn thì bảng không bảo đảm gì (cần datasheet chip thật / SME). */
  led(c){const head=c.mode==="high"?c.voh-c.vf:c.vs-c.vf-c.vol;
    if([c.vs,c.vf,c.vol,c.voh,c.i].some(x=>!isFinite(x)))return{ok:false,err:"Thiếu hoặc sai một thông số (dùng dấu phẩy hoặc dấu chấm cho số thập phân)."};
    if(!(c.i>0))return{ok:false,err:"Dòng LED mong muốn phải lớn hơn 0 mA."};
    if(!(head>0))return{ok:false,err:`Điện áp còn lại cho điện trở là ${NTE5.f(head,2)} V ≤ 0: nguồn không đủ để LED sáng.`};
    const r=head/(c.i/1000),re=NTE5.e12(r,1),ir=head/re*1000,pr=ir*ir*re/1000,pl=ir*c.vf,tot=ir*(c.n||1);
    const warn=[];
    if(c.mode==="high"&&isFinite(c.ioh)&&ir*1000>Math.abs(c.ioh))warn.push(`Bảng chỉ bảo đảm V_OH ≥ ${NTE5.f(c.voh,2)} V khi I_OH = −${NTE5.f(Math.abs(c.ioh),1)} µA (điều kiện đo của V_OH, không phải dòng cấp lớn nhất của chân). Dòng cấp ${NTE5.f(ir,2)} mA lớn hơn điều kiện đo: bảng không bảo đảm V_OH, nên R tính theo V_OH không chắc đúng, và bảng không cho biết chân cấp được dòng này; phải tra datasheet của chip thật (SME xác nhận). Chân 8051 mức 1 chỉ có pull-up yếu: nên nối tích cực mức thấp hoặc dùng tầng đệm.`);
    if(isFinite(c.pin)&&ir>c.pin)warn.push(`Dòng mỗi chân ${NTE5.f(ir,2)} mA vượt giới hạn ${NTE5.f(c.pin,1)} mA.`);
    if(isFinite(c.port)&&tot>c.port)warn.push(`Tổng ${c.n} LED = ${NTE5.f(tot,2)} mA vượt giới hạn cổng ${NTE5.f(c.port,1)} mA.`);
    return{ok:true,head,r,re,ir,pr,pl,tot,warn}},
  /* phân loại điện áp vào theo VIL(max), VIH(min) */
  level(v,vil,vih){if(!isFinite(v))return"";return v<=vil?"0":v>=vih?"1":"?"},
  /* biên nhiễu: NMH = VOH(min) − VIH(min), NML = VIL(max) − VOL(max) */
  margins(voh,vih,vil,vol){return{nmh:voh-vih,nml:vil-vol}},
  /* số kiểu Việt: dấu phẩy thập phân, bỏ số 0 thừa */
  f(x,d){if(!isFinite(x))return"—";let s=x.toFixed(d);if(s.includes("."))s=s.replace(/0+$/,"").replace(/\.$/,"");return s.replace(".",",").replace("-","−")},
  ohm(r){return r>=1000?NTE5.f(r/1000,2)+" kΩ":NTE5.f(r,1)+" Ω"}
};
function makeNtLedCalc(el,cfg){
  cfg=cfg||{};const P="ntl-"+(cfg.id||"x"),d=Object.assign({mode:"low",vs:"5",vf:"2",vol:"0,45",voh:"2,4",ioh:"−60",i:"5",n:"1",pin:"10",port:"15",v:"1,2",vil:"0,9",vih:"1,9"},cfg.d||{});
  const fld=(k,lab,u)=>`<label class="nt5-f"><span>${lab}</span><span class="nt5-iu"><input id="${P}-${k}" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" value="${d[k]}"><i>${u}</i></span></label>`;
  el.classList.add("nt5-calc");
  el.innerHTML=`<fieldset class="nt5-box"><legend>Điện trở hạn dòng cho LED</legend>
    <div class="nt5-mode" role="radiogroup" aria-label="Kiểu nối LED"><label><input type="radio" name="${P}-m" value="low"${d.mode==="low"?" checked":""}> Tích cực mức thấp (nguồn → R → LED → chân)</label><label><input type="radio" name="${P}-m" value="high"${d.mode==="high"?" checked":""}> Tích cực mức cao (chân → R → LED → GND)</label></div>
    <div class="nt5-grid">${fld("vs","Nguồn V<sub>CC</sub>","V")}${fld("vf","V<sub>F</sub> của LED","V")}${fld("vol","V<sub>OL</sub> của chân","V")}${fld("voh","V<sub>OH</sub> của chân","V")}${fld("ioh","I<sub>OH</sub> khi đo V<sub>OH</sub>","µA")}${fld("i","Dòng LED mong muốn","mA")}${fld("n","Số LED sáng cùng cổng","")}${fld("pin","Giới hạn mỗi chân","mA")}${fld("port","Giới hạn mỗi cổng","mA")}</div>
    <p class="nt-err" id="${P}-err" role="status" aria-live="polite"></p>
    <dl class="nt-out" aria-live="polite"><dt>Điện áp trên R</dt><dd id="${P}-h"></dd><dt>R tính được</dt><dd id="${P}-r"></dd><dt>Chọn E12 (≥ R)</dt><dd id="${P}-re"></dd><dt>Dòng thực</dt><dd id="${P}-ir"></dd><dt>Công suất trên R</dt><dd id="${P}-pr"></dd><dt>Tổng dòng cổng</dt><dd id="${P}-t"></dd><dt>Kiểm tra</dt><dd id="${P}-ck"></dd></dl></fieldset>
   <fieldset class="nt5-box"><legend>Điện áp vào là mức 0 hay mức 1?</legend>
    <div class="nt5-grid">${fld("v","Điện áp đo ở chân vào","V")}${fld("vil","V<sub>IL</sub> (max)","V")}${fld("vih","V<sub>IH</sub> (min)","V")}</div>
    <div class="nt5-bar" aria-hidden="true"><span class="z0" id="${P}-z0"></span><span class="zq" id="${P}-zq"></span><span class="z1" id="${P}-z1"></span><b id="${P}-pt"></b></div>
    <p class="nt5-lv" id="${P}-lv" role="status" aria-live="polite"></p></fieldset>
   <p class="mt-cap">Số mặc định là giả định của bài, không phải thông số của một chip cụ thể. I<sub>OH</sub> = −60 µA là điều kiện đo của V<sub>OH</sub> (dấu trừ = dòng chảy ra khỏi chân), không phải dòng cấp lớn nhất của chân. Mô hình bỏ qua việc V<sub>F</sub> và V<sub>OL</sub> thay đổi theo dòng.</p>`;
  const $=s=>el.querySelector("#"+P+"-"+s),g=k=>NTE5.num($(k).value);
  function calc(){const mode=el.querySelector(`input[name="${P}-m"]:checked`).value;
    $("vol").disabled=mode==="high";$("voh").disabled=$("ioh").disabled=mode!=="high";
    const r=NTE5.led({mode,vs:g("vs"),vf:g("vf"),vol:mode==="high"?0:g("vol"),voh:mode==="high"?g("voh"):0,ioh:g("ioh"),i:g("i"),n:Math.max(1,Math.round(g("n")||1)),pin:g("pin"),port:g("port")});
    ["h","r","re","ir","pr","t","ck"].forEach(k=>$(k).textContent="");
    if(!r.ok){$("err").textContent=r.err;return}
    $("err").textContent="";$("h").textContent=NTE5.f(r.head,2)+" V";$("r").textContent=NTE5.ohm(r.r);$("re").textContent=NTE5.ohm(r.re);
    $("ir").textContent=NTE5.f(r.ir,2)+" mA";$("pr").textContent=NTE5.f(r.pr,1)+" mW";$("t").textContent=NTE5.f(r.tot,2)+" mA";
    $("ck").textContent=r.warn.length?r.warn.join(" "):"Trong giới hạn đã nhập.";$("ck").className=r.warn.length?"bad-t":"ok-t"}
  function lv(){const v=g("v"),vil=g("vil"),vih=g("vih"),mx=Math.max(5,v||0,vih||0);
    if(!(vil<vih)||!isFinite(v)){$("lv").textContent="Nhập V, VIL < VIH.";return}
    $("z0").style.width=(vil/mx*100)+"%";$("zq").style.width=((vih-vil)/mx*100)+"%";$("z1").style.width=((mx-vih)/mx*100)+"%";
    $("pt").style.left=`calc(${Math.min(100,Math.max(0,v/mx*100))}% - 2px)`;
    const L=NTE5.level(v,vil,vih);
    $("lv").textContent=L==="0"?`${NTE5.f(v,2)} V ≤ VIL: chip đọc chắc chắn là mức 0.`:L==="1"?`${NTE5.f(v,2)} V ≥ VIH: chip đọc chắc chắn là mức 1.`:`${NTE5.f(v,2)} V nằm giữa VIL và VIH: vùng không xác định, chip có thể đọc 0 hoặc 1.`;
    $("lv").className="nt5-lv "+(L==="?"?"bad-t":"ok-t")}
  el.querySelectorAll("input").forEach(x=>x.addEventListener("input",()=>{calc();lv()}));
  calc();lv()}
/* ---- dữ liệu và lời gọi của bài ---- */
/* Bài 5 · Điện áp, dòng và mức logic (FND-005) — sinh bởi tools/author/nentang/m05.py, không sửa tay.
   Bảng bit tương tác, phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeNtLedCalc(document.getElementById("led-l5"),{"id": "l5"});
makeMtLab(document.getElementById("lab-l5"),{id:"l5",scenarios:[{"label": "Ví dụ: Định luật Ohm trên điện trở 1 kΩ", "note": "Tính dòng, công suất; viết phương trình vòng cho mạch LED.", "steps": [{"t": "Điện trở 1 kΩ nối giữa +5 V và GND", "html": "<p class=\"mt-calc\">V = 5 V · R = 1 kΩ · I = ?<\/p>", "say": "<p>Định luật Ohm: I = V ÷ R. Dùng mA và kΩ cho gọn: V ÷ kΩ = mA.<\/p>"}, {"t": "I = 5 V ÷ 1 kΩ = 5 mA", "html": "<p class=\"mt-calc\">I = 5 V ÷ 1 kΩ = <b>5 mA<\/b><\/p>", "ask": {"q": "Đổi R thành 2 kΩ, giữ 5 V. Dòng bằng bao nhiêu?", "o": ["10 mA", "2,5 mA", "5 mA"], "a": 1}}, {"t": "Công suất P = V × I = 25 mW", "html": "<p class=\"mt-calc\">P = 5 V × 5 mA = <b>25 mW<\/b> = I² × R = 5² × 1 = 25 mW<\/p>", "say": "<p>Điện trở biến điện năng thành nhiệt. Điện trở dán cỡ nhỏ thường chịu khoảng vài chục tới vài trăm mW: tra datasheet của đúng loại điện trở.<\/p>"}, {"t": "Vòng LED: 5 V = V_R + V_F + V_OL", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 300 210\" role=\"img\" aria-label=\"Mạch LED tích cực mức thấp: +5 V, R, LED, chân P\u0031.0 ở mức 0\"><text x=\"120\" y=\"16\" text-anchor=\"middle\" class=\"mono\">+5 V<\/text><path class=\"wire on\" d=\"M120 22v14\"/><rect class=\"part on\" x=\"113\" y=\"36\" width=\"14\" height=\"36\" rx=\"2\"/><text x=\"136\" y=\"58\" text-anchor=\"start\">R<\/text><path class=\"wire on\" d=\"M120 72v24\"/><polygon class=\"part on\" points=\"109,96 131,96 120,114\"/><path class=\"wire\" d=\"M109 114h22\"/><path class=\"wire on\" d=\"M133 102l10 -8M133 109l10 -8\"/><text x=\"154\" y=\"112\" text-anchor=\"start\">LED<\/text><path class=\"wire on\" d=\"M120 114v40\"/><rect class=\"part\" x=\"72\" y=\"154\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"120\" y=\"171\" text-anchor=\"middle\" class=\"mono\">P\u0031.0<\/text><text x=\"120\" y=\"187\" text-anchor=\"middle\" class=\"sm muted\">mức 0<\/text><text x=\"96\" y=\"80\" text-anchor=\"end\" class=\"sm acc\">I<\/text><path class=\"wire accs\" d=\"M106 62v22l-4 -6M106 84l4 -6\"/><\/svg><p class=\"mt-calc\">Định luật Kirchhoff về điện áp: tổng sụt áp quanh vòng = nguồn<\/p>", "say": "<p>Đi một vòng từ +5 V qua R, qua LED, vào chân rồi xuống GND bên trong chip: tổng các sụt áp bằng 5 V. Đây là phương trình dùng cho mọi phép tính LED trong bài.<\/p>"}]}, {"label": "Ví dụ: Điện áp vào là mức 0, mức 1 hay không rõ", "note": "So điện áp vào với VIL(max) = 0,9 V và VIH(min) = 1,9 V (giả định).", "steps": [{"t": "Bảng DC giả định của bài", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thông số<\/th><th scope=\"col\">Giá trị giả định<\/th><th scope=\"col\">Nghĩa<\/th><\/tr><\/thead><tbody><tr><td>V<sub>IL<\/sub> (max)<\/td><td class=\"new\">0,9 V<\/td><td>điện áp vào cao nhất vẫn được đọc là 0<\/td><\/tr><tr><td>V<sub>IH<\/sub> (min)<\/td><td class=\"new\">1,9 V<\/td><td>điện áp vào thấp nhất đã được đọc là 1<\/td><\/tr><tr><td>V<sub>OL<\/sub> (max)<\/td><td>0,45 V<\/td><td>ra mức 0, khi chân hút 1,6 mA<\/td><\/tr><tr><td>V<sub>OH<\/sub> (min)<\/td><td>2,4 V<\/td><td>ra mức 1, đo khi I<sub>OH<\/sub> = −60 µA (điều kiện đo của V<sub>OH<\/sub>, dấu trừ = dòng chảy ra khỏi chân); không phải dòng cấp lớn nhất của chân<\/td><\/tr><tr><td>I<sub>OL<\/sub> mỗi chân<\/td><td>10 mA<\/td><td>dòng hút lớn nhất cho phép<\/td><\/tr><tr><td>Tổng mỗi cổng 8 chân<\/td><td>15 mA<\/td><td>cộng dòng hút của cả cổng<\/td><\/tr><\/tbody><\/table>", "say": "<p>Mỗi datasheet có bảng “DC Characteristics”. Bài dùng các số giả định này để luyện cách đọc; khi làm thật phải tra datasheet của đúng chip và đúng điện áp nguồn.<\/p>"}, {"t": "Vào 0,3 V: mức 0 chắc chắn", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Điện áp vào<\/th><th scope=\"col\">Vùng<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td>≥ 1,9 V<\/td><td>Mức 1<\/td><td>chip chắc chắn đọc 1<\/td><\/tr><tr><td>0,9 … 1,9 V<\/td><td>Không xác định<\/td><td>có thể đọc 0 hoặc 1<\/td><\/tr><tr><td class=\"new\">≤ 0,9 V<\/td><td class=\"new\">Mức 0<\/td><td class=\"new\">chip chắc chắn đọc 0<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">0,3 V ≤ VIL = 0,9 V<\/p>"}, {"t": "Vào 1,2 V: không xác định", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Điện áp vào<\/th><th scope=\"col\">Vùng<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td>≥ 1,9 V<\/td><td>Mức 1<\/td><td>chip chắc chắn đọc 1<\/td><\/tr><tr><td class=\"bad\">0,9 … 1,9 V<\/td><td class=\"bad\">Không xác định<\/td><td class=\"bad\">có thể đọc 0 hoặc 1<\/td><\/tr><tr><td>≤ 0,9 V<\/td><td>Mức 0<\/td><td>chip chắc chắn đọc 0<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">1,2 V nằm giữa 0,9 V và 1,9 V<\/p>", "ask": {"q": "1,2 V lớn hơn VIL(max) = 0,9 V. Chip đọc là gì?", "o": ["Mức 1", "Mức 0", "Không xác định"], "a": 2}, "say": "<p>Lớn hơn VIL chưa đủ để thành mức 1: phải đạt VIH. Vùng giữa không được datasheet bảo đảm, kết quả có thể khác giữa các chip, nhiệt độ, lần đọc.<\/p>"}, {"t": "Vào 2,4 V: mức 1 chắc chắn", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Điện áp vào<\/th><th scope=\"col\">Vùng<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td class=\"new\">≥ 1,9 V<\/td><td class=\"new\">Mức 1<\/td><td class=\"new\">chip chắc chắn đọc 1<\/td><\/tr><tr><td>0,9 … 1,9 V<\/td><td>Không xác định<\/td><td>có thể đọc 0 hoặc 1<\/td><\/tr><tr><td>≤ 0,9 V<\/td><td>Mức 0<\/td><td>chip chắc chắn đọc 0<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">2,4 V ≥ VIH = 1,9 V<\/p>"}, {"t": "Vào 4,8 V: mức 1 chắc chắn", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Điện áp vào<\/th><th scope=\"col\">Vùng<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td class=\"new\">≥ 1,9 V<\/td><td class=\"new\">Mức 1<\/td><td class=\"new\">chip chắc chắn đọc 1<\/td><\/tr><tr><td>0,9 … 1,9 V<\/td><td>Không xác định<\/td><td>có thể đọc 0 hoặc 1<\/td><\/tr><tr><td>≤ 0,9 V<\/td><td>Mức 0<\/td><td>chip chắc chắn đọc 0<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">4,8 V ≥ VIH = 1,9 V<\/p>"}]}, {"label": "Ví dụ: Điện trở cho LED trên P\u0031.0", "note": "V_R, R, chọn E12, dòng thực, công suất; lệnh CLR / SETB P\u0031.0.", "steps": [{"t": "LED đỏ trên P\u0031.0, nối tích cực mức thấp", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 300 210\" role=\"img\" aria-label=\"LED tích cực mức thấp, chân đang ở mức 1, LED tắt\"><text x=\"120\" y=\"16\" text-anchor=\"middle\" class=\"mono\">+5 V<\/text><path class=\"wire\" d=\"M120 22v14\"/><rect class=\"part\" x=\"113\" y=\"36\" width=\"14\" height=\"36\" rx=\"2\"/><text x=\"136\" y=\"58\" text-anchor=\"start\">R = ?<\/text><path class=\"wire\" d=\"M120 72v24\"/><polygon class=\"part\" points=\"109,96 131,96 120,114\"/><path class=\"wire\" d=\"M109 114h22\"/><path class=\"wire off\" d=\"M133 102l10 -8M133 109l10 -8\"/><text x=\"154\" y=\"112\" text-anchor=\"start\">V_F = 2,0 V<\/text><path class=\"wire\" d=\"M120 114v40\"/><rect class=\"part\" x=\"72\" y=\"154\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"120\" y=\"171\" text-anchor=\"middle\" class=\"mono\">P\u0031.0<\/text><text x=\"120\" y=\"187\" text-anchor=\"middle\" class=\"sm muted\">mức 1<\/text><\/svg>", "say": "<p>Giả định: V<sub>F<\/sub> = 2,0 V, V<sub>OL<\/sub> = 0,45 V, cần 5 mA. Chân ở mức 1 thì hai đầu LED gần như cùng điện áp nên LED tắt.<\/p>"}, {"t": "V_R = 5 − 2,0 − 0,45 = 2,55 V", "html": "<p class=\"mt-calc\">V_R = V_CC − V_F − V_OL = 5 − 2,0 − 0,45 = <b>2,55 V<\/b><\/p>"}, {"t": "R = 2,55 V ÷ 5 mA = 510 Ω", "html": "<p class=\"mt-calc\">R = 2,55 V ÷ 5 mA = <b>510 Ω<\/b><\/p>", "ask": {"q": "510 Ω không có trong dãy E12. Chọn giá trị chuẩn nào?", "o": ["560 Ω (lớn hơn, dòng nhỏ hơn 5 mA)", "470 Ω (nhỏ hơn, dòng lớn hơn 5 mA)"], "a": 0}}, {"t": "Chọn 560 Ω: I = 4,55 mA, P_R = 11,6 mW", "html": "<p class=\"mt-calc\">I = 2,55 V ÷ 560 Ω = <b>4,55 mA<\/b> · P_R = I² × R = <b>11,6 mW<\/b><\/p>", "say": "<p>Điện trở hạn dòng làm tròn LÊN để dòng không vượt mục tiêu. 4,55 mA dưới giới hạn 10 mA mỗi chân (giả định).<\/p>"}, {"t": "CLR P\u0031.0 → C2H 90H: chân xuống mức 0, LED sáng", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 300 210\" role=\"img\" aria-label=\"Sau CLR P\u0031.0: chân mức 0, LED sáng, dòng 4,55 mA\"><text x=\"120\" y=\"16\" text-anchor=\"middle\" class=\"mono\">+5 V<\/text><path class=\"wire on\" d=\"M120 22v14\"/><rect class=\"part on\" x=\"113\" y=\"36\" width=\"14\" height=\"36\" rx=\"2\"/><text x=\"136\" y=\"58\" text-anchor=\"start\">560 Ω<\/text><path class=\"wire on\" d=\"M120 72v24\"/><polygon class=\"part on\" points=\"109,96 131,96 120,114\"/><path class=\"wire\" d=\"M109 114h22\"/><path class=\"wire on\" d=\"M133 102l10 -8M133 109l10 -8\"/><text x=\"154\" y=\"112\" text-anchor=\"start\">V_F = 2,0 V<\/text><path class=\"wire on\" d=\"M120 114v40\"/><rect class=\"part\" x=\"72\" y=\"154\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"120\" y=\"171\" text-anchor=\"middle\" class=\"mono\">P\u0031.0<\/text><text x=\"120\" y=\"187\" text-anchor=\"middle\" class=\"sm muted\">mức 0<\/text><text x=\"96\" y=\"80\" text-anchor=\"end\" class=\"sm acc\">4,55 mA<\/text><path class=\"wire accs\" d=\"M106 62v22l-4 -6M106 84l4 -6\"/><\/svg><p class=\"mt-calc\">CLR P\u0031.0 → C2H 90H (1 chu kỳ máy) · SETB P\u0031.0 → D2H 90H: LED tắt<\/p>", "say": "<p>Mã máy chép từ sdas8051; trạng thái P\u0031 = FEH sau CLR P\u0031.0 đối chiếu bằng ucsim s51. Trình giả lập chỉ cho mức logic, không cho dòng điện: dòng là phép tính với thông số giả định.<\/p>"}]}, {"label": "Ví dụ: Biên nhiễu giữa hai chip", "note": "So mức ra xấu nhất của chip phát với ngưỡng vào của chip nhận.", "steps": [{"t": "Chip A phát, chip B nhận trên cùng một dây", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">Chip A (phát)<\/th><th scope=\"col\">Chip B (nhận)<\/th><\/tr><\/thead><tbody><tr><td>Mức 0<\/td><td>V_OL ≤ 0,45 V<\/td><td>V_IL ≤ 0,9 V<\/td><\/tr><tr><td>Mức 1<\/td><td>V_OH ≥ 2,4 V<\/td><td>V_IH ≥ 1,9 V<\/td><\/tr><\/tbody><\/table>", "say": "<p>Ghép hai chip: so mức RA xấu nhất của chip phát với ngưỡng VÀO của chip nhận. Số liệu là giả định của bài.<\/p>"}, {"t": "NML = 0,9 − 0,45 = 0,45 V", "html": "<p class=\"mt-calc\">NML = V_IL(max) − V_OL(max) = 0,9 − 0,45 = <b>0,45 V<\/b><\/p>", "say": "<p>Nhiễu cộng vào dây khi đang ở mức 0 phải nhỏ hơn 0,45 V thì B vẫn chắc chắn đọc 0.<\/p>"}, {"t": "NMH = 2,4 − 1,9 = 0,5 V", "html": "<p class=\"mt-calc\">NMH = V_OH(min) − V_IH(min) = 2,4 − 1,9 = <b>0,5 V<\/b><\/p>"}, {"t": "Nhiễu 0,6 V trên mức 0: 1,05 V rơi vào vùng không xác định", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Điện áp vào<\/th><th scope=\"col\">Vùng<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td>≥ 1,9 V<\/td><td>Mức 1<\/td><td>chip chắc chắn đọc 1<\/td><\/tr><tr><td class=\"bad\">0,9 … 1,9 V<\/td><td class=\"bad\">Không xác định<\/td><td class=\"bad\">có thể đọc 0 hoặc 1<\/td><\/tr><tr><td>≤ 0,9 V<\/td><td>Mức 0<\/td><td>chip chắc chắn đọc 0<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">0,45 + 0,6 = <b>1,05 V<\/b> > V_IL(max) = 0,9 V<\/p>", "ask": {"q": "Mức 0 (0,45 V) bị nhiễu cộng 0,6 V. B đọc chắc chắn là 0 không?", "o": ["Có: 1,05 V < 1,9 V", "Không: 1,05 V > 0,9 V"], "a": 1}, "say": "<p>Nhiễu lớn hơn biên nhiễu thì không còn bảo đảm. Cách sửa: dây ngắn hơn, nối đất tốt, hoặc chọn chip có biên nhiễu lớn hơn.<\/p>"}]}, {"label": "Lỗi: LED không có điện trở hạn dòng", "note": "Dòng không bị giới hạn bởi thiết kế; VOL của datasheet không còn đúng.", "steps": [{"t": "LED nối thẳng từ +5 V vào chân, không có R", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 300 210\" role=\"img\" aria-label=\"LED nối thẳng không có điện trở hạn dòng\"><text x=\"120\" y=\"16\" text-anchor=\"middle\" class=\"mono\">+5 V<\/text><path class=\"wire on\" d=\"M120 22v14\"/><path class=\"wire on\" d=\"M120 36v60\"/><text x=\"136\" y=\"66\" text-anchor=\"start\" class=\"sm err\">không có R<\/text><polygon class=\"part on\" points=\"109,96 131,96 120,114\"/><path class=\"wire\" d=\"M109 114h22\"/><path class=\"wire on\" d=\"M133 102l10 -8M133 109l10 -8\"/><text x=\"154\" y=\"112\" text-anchor=\"start\">LED<\/text><path class=\"wire on\" d=\"M120 114v40\"/><rect class=\"part\" x=\"72\" y=\"154\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"120\" y=\"171\" text-anchor=\"middle\" class=\"mono\">P\u0031.0<\/text><text x=\"120\" y=\"187\" text-anchor=\"middle\" class=\"sm muted\">mức 0<\/text><\/svg>", "say": "<p>Mạch này vẫn “chạy” lúc đầu: LED sáng rất mạnh. Lỗi nằm ở chỗ không có gì đặt giới hạn cho dòng.<\/p>"}, {"t": "Phương trình: 5 = V_F + V_OL + I × 0", "html": "<p class=\"mt-calc\">I = (5 − 2,0 − 0,45) ÷ 0 Ω → không xác định bằng định luật Ohm<\/p>", "ask": {"q": "Với R = 0, điều gì quyết định dòng?", "o": ["Lệnh CLR P\u0031.0 tự giới hạn dòng", "VOL luôn giữ dòng ở 1,6 mA", "Điện trở trong của chân và LED: dòng dễ vượt 10 mA"], "a": 2}}, {"t": "Có thể vượt giới hạn dòng: LED và chân có thể hỏng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Kiểm tra<\/th><th scope=\"col\">Giá trị<\/th><th scope=\"col\">Kết quả<\/th><\/tr><\/thead><tbody><tr><td>Dòng mỗi chân<\/td><td>không giới hạn bởi thiết kế<\/td><td class=\"bad\">có thể vượt 10 mA (ước lượng, chưa đo)<\/td><\/tr><tr><td>V_OL<\/td><td>không còn 0,45 V (chỉ đúng ở 1,6 mA)<\/td><td class=\"bad\">không dùng được số datasheet<\/td><\/tr><\/tbody><\/table>", "say": "<p>VOL trong datasheet đi kèm điều kiện đo (ở đây 1,6 mA); dòng lớn hơn thì VOL tăng và chip nóng lên. Giới hạn tuyệt đối (absolute maximum) không phải điểm làm việc. Bài chưa đo dòng này trên board: “có thể vượt 10 mA” là suy luận định tính (không có gì trong mạch giới hạn dòng), không phải số đo.<\/p>"}, {"t": "Sửa: thêm R = 560 Ω, I = 4,55 mA", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 300 210\" role=\"img\" aria-label=\"Đã thêm điện trở 560 Ω\"><text x=\"120\" y=\"16\" text-anchor=\"middle\" class=\"mono\">+5 V<\/text><path class=\"wire on\" d=\"M120 22v14\"/><rect class=\"part on\" x=\"113\" y=\"36\" width=\"14\" height=\"36\" rx=\"2\"/><text x=\"136\" y=\"58\" text-anchor=\"start\">560 Ω<\/text><path class=\"wire on\" d=\"M120 72v24\"/><polygon class=\"part on\" points=\"109,96 131,96 120,114\"/><path class=\"wire\" d=\"M109 114h22\"/><path class=\"wire on\" d=\"M133 102l10 -8M133 109l10 -8\"/><text x=\"154\" y=\"112\" text-anchor=\"start\">LED<\/text><path class=\"wire on\" d=\"M120 114v40\"/><rect class=\"part\" x=\"72\" y=\"154\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"120\" y=\"171\" text-anchor=\"middle\" class=\"mono\">P\u0031.0<\/text><text x=\"120\" y=\"187\" text-anchor=\"middle\" class=\"sm muted\">mức 0<\/text><text x=\"96\" y=\"80\" text-anchor=\"end\" class=\"sm acc\">4,55 mA<\/text><path class=\"wire accs\" d=\"M106 62v22l-4 -6M106 84l4 -6\"/><\/svg><p class=\"mt-calc\">I = 2,55 ÷ 560 = 4,55 mA ≤ 10 mA ✓<\/p>"}]}, {"label": "Bẫy: LED tích cực mức cao trên chân 8051", "note": "Chân mức 1 chỉ có pull-up yếu; bảng chỉ bảo đảm V_OH khi I_OH = −60 µA (điều kiện đo).", "steps": [{"t": "Nối ngược: chân → R → LED → GND", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 300 190\" role=\"img\" aria-label=\"LED tích cực mức cao trên chân 8051\"><rect class=\"part\" x=\"72\" y=\"10\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"120\" y=\"27\" text-anchor=\"middle\" class=\"mono\">P\u0031.0<\/text><text x=\"120\" y=\"43\" text-anchor=\"middle\" class=\"sm muted\">mức 1<\/text><path class=\"wire\" d=\"M120 50v14\"/><rect class=\"part\" x=\"113\" y=\"64\" width=\"14\" height=\"36\" rx=\"2\"/><text x=\"136\" y=\"86\" text-anchor=\"start\">R<\/text><path class=\"wire\" d=\"M120 100v20\"/><polygon class=\"part\" points=\"109,120 131,120 120,138\"/><path class=\"wire\" d=\"M109 138h22\"/><path class=\"wire off\" d=\"M133 126l10 -8M133 133l10 -8\"/><text x=\"154\" y=\"136\" text-anchor=\"start\">LED<\/text><path class=\"wire\" d=\"M120 138v22\"/><path class=\"wire\" d=\"M120 160v8M108 168h24M113 173h14M118 178h4\"/><\/svg>", "say": "<p>Muốn LED sáng khi chân ở mức 1. Trên giấy: R = (V_OH − V_F) ÷ I.<\/p>"}, {"t": "Trên giấy: R = (2,4 − 2,0) ÷ 5 mA = 80 Ω", "html": "<p class=\"mt-calc\">R = (2,4 − 2,0) V ÷ 5 mA = 80 Ω<\/p>", "ask": {"q": "Bảng DC giả định có bảo đảm chân 8051 ở mức 1 cấp được 5 mA không?", "o": ["Có: mọi chân cấp được 10 mA ở cả hai mức", "Không: bảng chỉ bảo đảm V_OH ≥ 2,4 V khi I_OH = −60 µA (điều kiện đo); mức 1 chỉ có pull-up yếu"], "a": 1}}, {"t": "Mức 1: bảng chỉ bảo đảm V_OH khi I_OH = −60 µA", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Mức của chân<\/th><th scope=\"col\">Thành phần dẫn dòng<\/th><th scope=\"col\">Bảng DC giả định ghi<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>transistor kéo xuống mạnh<\/td><td>hút tới 10 mA mỗi chân<\/td><\/tr><tr><td>1<\/td><td>pull-up yếu bên trong<\/td><td class=\"bad\">V<sub>OH<\/sub> ≥ 2,4 V chỉ khi I<sub>OH<\/sub> = −60 µA (điều kiện đo); 5 mA: không bảo đảm<\/td><\/tr><\/tbody><\/table>", "say": "<p>Cổng P\u0031, P\u0032, P\u0033 của 8051 kiểu gốc là cổng tựa hai chiều (quasi-bidirectional): ra mức 1 chỉ nhờ pull-up yếu. Bảng giả định ghi V<sub>OH<\/sub> ≥ 2,4 V khi I<sub>OH<\/sub> = −60 µA (điều kiện đo của V<sub>OH<\/sub>, dấu trừ = dòng chảy ra khỏi chân). Đây là điều kiện đo của bảng, không phải dòng cấp lớn nhất của chân. 5 mA lớn hơn điều kiện đo nhiều lần: bảng không bảo đảm V<sub>OH<\/sub> ở dòng đó, cũng không cho biết chân cấp được bao nhiêu (phải tra datasheet của chip thật, chờ SME xác nhận). Với pull-up yếu, LED nối kiểu này rất mờ hoặc không sáng.<\/p>"}, {"t": "Sửa: đổi sang tích cực mức thấp (hoặc dùng tầng đệm, Bài 6)", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 300 210\" role=\"img\" aria-label=\"Sửa thành LED tích cực mức thấp\"><text x=\"120\" y=\"16\" text-anchor=\"middle\" class=\"mono\">+5 V<\/text><path class=\"wire on\" d=\"M120 22v14\"/><rect class=\"part on\" x=\"113\" y=\"36\" width=\"14\" height=\"36\" rx=\"2\"/><text x=\"136\" y=\"58\" text-anchor=\"start\">560 Ω<\/text><path class=\"wire on\" d=\"M120 72v24\"/><polygon class=\"part on\" points=\"109,96 131,96 120,114\"/><path class=\"wire\" d=\"M109 114h22\"/><path class=\"wire on\" d=\"M133 102l10 -8M133 109l10 -8\"/><text x=\"154\" y=\"112\" text-anchor=\"start\">LED<\/text><path class=\"wire on\" d=\"M120 114v40\"/><rect class=\"part\" x=\"72\" y=\"154\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"120\" y=\"171\" text-anchor=\"middle\" class=\"mono\">P\u0031.0<\/text><text x=\"120\" y=\"187\" text-anchor=\"middle\" class=\"sm muted\">mức 0<\/text><text x=\"96\" y=\"80\" text-anchor=\"end\" class=\"sm acc\">4,55 mA<\/text><path class=\"wire accs\" d=\"M106 62v22l-4 -6M106 84l4 -6\"/><\/svg><p class=\"mt-calc\">Bật LED: CLR P\u0031.0 (C2H 90H)<\/p>"}]}, {"label": "Cảnh báo: 8 LED vượt tổng dòng cổng", "note": "Từng chân đạt nhưng tổng cổng vượt; giảm dòng hoặc dùng tầng đệm.", "steps": [{"t": "8 LED trên P\u0031, mỗi LED 4,55 mA", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số LED<\/th><th scope=\"col\">Dòng mỗi LED<\/th><th scope=\"col\">Tổng<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>4,55 mA<\/td><td>4,55 mA<\/td><\/tr><tr><td>8<\/td><td>4,55 mA<\/td><td>36,4 mA<\/td><\/tr><\/tbody><\/table>", "say": "<p>MOV P\u0031,#00H (75H 90H 00H) đưa cả 8 chân xuống mức 0: cả 8 LED cùng sáng.<\/p>"}, {"t": "36,4 mA > 15 mA giới hạn cổng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Kiểm tra<\/th><th scope=\"col\">Cần<\/th><th scope=\"col\">Có<\/th><th scope=\"col\">Kết quả<\/th><\/tr><\/thead><tbody><tr><td>Mỗi chân<\/td><td>≤ 10 mA<\/td><td>4,55 mA<\/td><td class=\"ok\">Đạt<\/td><\/tr><tr><td>Cả cổng<\/td><td>≤ 15 mA<\/td><td>36,4 mA<\/td><td class=\"bad\">Vượt<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Mỗi chân đều dưới 10 mA. Mạch có đạt không?", "o": ["Không: tổng cổng 36,4 mA vượt 15 mA", "Có: chỉ cần xét từng chân"], "a": 0}}, {"t": "Dòng mỗi LED ≤ 15 ÷ 8 = 1,875 mA", "html": "<p class=\"mt-calc\">I ≤ 15 mA ÷ 8 = 1,875 mA → R ≥ 2,55 V ÷ 1,875 mA = <b>1 360 Ω<\/b><\/p>"}, {"t": "Chọn 1,5 kΩ: 1,7 mA mỗi LED, tổng 13,6 mA", "html": "<p class=\"mt-calc\">I = 2,55 ÷ 1,5 kΩ = <b>1,7 mA<\/b> · 8 × 1,7 = <b>13,6 mA<\/b> ≤ 15 mA ✓<\/p>", "say": "<p>LED sẽ tối hơn. Nếu cần đủ sáng ở 4–5 mA mỗi LED thì phải dùng tầng đệm (transistor, IC đệm) ở Bài 6.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l5"),"l5",[{"kind": "num", "t": "Định luật Ohm và biên nhiễu", "d": "<p>Tính và nhập số theo đơn vị ghi sau ô. Bảng DC giả định của bài: V<sub>IL<\/sub>(max) = 0,9 V, V<sub>IH<\/sub>(min) = 1,9 V, V<sub>OL<\/sub>(max) = 0,45 V, V<sub>OH<\/sub>(min) = 2,4 V.<\/p>", "items": [{"q": "Đặt 3,3 V lên điện trở 1,5 kΩ. Dòng qua điện trở", "a": 2.2, "tol": 0.005, "unit": "mA"}, {"q": "Dòng 4 mA chạy qua điện trở 680 Ω. Điện áp trên điện trở", "a": 2.72, "tol": 0.005, "unit": "V"}, {"q": "Công suất tỏa nhiệt trên điện trở ở câu trên", "a": 10.88, "tol": 0.05, "unit": "mW"}, {"q": "Biên nhiễu mức cao NMH = VOH(min) − VIH(min)", "a": 0.5, "tol": 0.005, "unit": "V"}, {"q": "Biên nhiễu mức thấp NML = VIL(max) − VOL(max)", "a": 0.45, "tol": 0.005, "unit": "V"}, {"q": "Đầu ra mức thấp 0,45 V bị nhiễu cộng thêm 0,5 V. Điện áp tới đầu vào", "a": 0.95, "tol": 0.005, "unit": "V"}], "hints": ["Định luật Ohm: V = I × R. Đổi đơn vị cho gọn: mA × kΩ = V, V ÷ kΩ = mA.", "Công suất trên điện trở: P = I² × R. Với I tính bằng mA và R bằng kΩ, kết quả là mW.", "Biên nhiễu là khoảng cách giữa mức ra xấu nhất của chip phát và ngưỡng vào của chip nhận: 2,4 − 1,9 và 0,9 − 0,45."], "why": "3,3 V ÷ 1,5 kΩ = 2,2 mA; 4 mA × 0,68 kΩ = 2,72 V; P = 4² × 0,68 = 10,88 mW; NMH = 2,4 − 1,9 = 0,5 V; NML = 0,9 − 0,45 = 0,45 V; 0,45 + 0,5 = 0,95 V lớn hơn VIL(max) = 0,9 V nên đã rơi vào vùng không xác định."}, {"kind": "num", "t": "Thiết kế điện trở cho LED", "d": "<p>LED nối tích cực mức thấp: +5 V → R → LED → chân P\u0031.0. Giả định: V<sub>F<\/sub> của LED = 1,8 V, V<sub>OL<\/sub> của chân = 0,45 V, dòng mong muốn 4 mA, giới hạn mỗi cổng 8 chân 15 mA. Điện trở chọn trong dãy chuẩn E12 (10, 12, 15, 18, 22, 27, 33, 39, 47, 56, 68, 82 × 10ⁿ Ω).<\/p>", "items": [{"q": "Điện áp còn lại trên điện trở", "a": 2.75, "tol": 0.005, "unit": "V"}, {"q": "Điện trở tính được", "a": 687.5, "tol": 0.5, "unit": "Ω"}, {"q": "Giá trị E12 chọn (không để dòng vượt 4 mA)", "a": 820, "tol": 0.5, "unit": "Ω"}, {"q": "Dòng thực với điện trở đã chọn", "a": 3.354, "tol": 0.01, "unit": "mA"}, {"q": "Công suất trên điện trở", "a": 9.22, "tol": 0.05, "unit": "mW"}, {"q": "Tổng dòng khi 4 LED cùng sáng trên một cổng", "a": 13.41, "tol": 0.02, "unit": "mA"}, {"q": "Số LED nhiều nhất được sáng cùng lúc trên cổng đó", "a": 4, "tol": 0, "unit": "LED"}], "hints": ["Đi một vòng mạch: 5 V = V_R + V_F + V_OL, nên V_R = 5 − 1,8 − 0,45.", "R = V_R ÷ I. Điện trở hạn dòng làm tròn LÊN giá trị chuẩn gần nhất để dòng không vượt mục tiêu: 680 Ω nhỏ hơn 687,5 Ω nên không dùng được.", "Dòng thực = 2,75 V ÷ 0,82 kΩ. Số LED tối đa = phần nguyên của 15 mA ÷ dòng thực."], "why": "V_R = 2,75 V; R = 2,75 ÷ 4 mA = 687,5 Ω → E12 lên 820 Ω; I = 2,75 ÷ 0,82 = 3,354 mA; P = 3,354² × 0,82 ≈ 9,22 mW; 4 LED = 13,41 mA ≤ 15 mA; 5 LED = 16,77 mA vượt, nên tối đa 4 LED."}, {"kind": "pick", "t": "Đọc tình huống theo datasheet", "d": "<p>Mỗi dòng là một tình huống. Dùng bảng DC giả định: V<sub>IL<\/sub>(max) 0,9 V, V<sub>IH<\/sub>(min) 1,9 V, V<sub>OL<\/sub> 0,45 V, V<sub>OH<\/sub>(min) 2,4 V khi I<sub>OH<\/sub> = −60 µA (điều kiện đo của V<sub>OH<\/sub>, dấu trừ = dòng chảy ra khỏi chân; không phải dòng cấp lớn nhất của chân), chân 8051 mức 1 chỉ có pull-up yếu, giới hạn 10 mA mỗi chân, 15 mA mỗi cổng; LED V<sub>F<\/sub> = 2,0 V, nguồn 5 V. Chọn nhóm đúng cho từng dòng.<\/p>", "cats": ["Đạt", "Vùng không xác định", "Vượt giới hạn dòng", "Mức 1 không được bảo đảm ở dòng cần"], "items": [{"q": "Đầu vào đo được 1,4 V", "a": 1}, {"q": "Đầu vào đo được 0,5 V; mạch cần chip đọc mức 0", "a": 0}, {"q": "Một LED tích cực mức thấp với R = 470 Ω", "a": 0}, {"q": "LED nối thẳng từ +5 V vào chân, không có điện trở, chân ở mức 0", "a": 2}, {"q": "LED tích cực mức cao (chân → R → LED → GND) cần 5 mA", "a": 3}, {"q": "6 LED cùng sáng trên một cổng, mỗi LED 3 mA", "a": 2}, {"q": "Đầu ra mức cao 2,4 V nối vào đầu vào của chip khác có VIH(min) 3,5 V, VIL(max) 1,5 V", "a": 1}, {"q": "3 LED tích cực mức thấp cùng sáng, mỗi LED 4,55 mA", "a": 0}], "hints": ["Với điện áp vào: ≤ VIL(max) là mức 0, ≥ VIH(min) là mức 1, ở giữa là không xác định. Ngưỡng là của chip NHẬN.", "Với LED: tính dòng một LED = (5 − 2,0 − 0,45) ÷ R, rồi so với 10 mA và nhân số LED để so với 15 mA.", "Bảng chỉ bảo đảm V<sub>OH<\/sub> ở I<sub>OH<\/sub> = −60 µA (điều kiện đo, không phải dòng cấp lớn nhất). Mạch nào cần chân 8051 cấp vài mA ở mức 1 thì bảng không bảo đảm, và chân chỉ có pull-up yếu."], "why": "1,4 V nằm giữa 0,9 và 1,9 V; 0,5 V ≤ 0,9 V; 2,55 V ÷ 470 Ω = 5,43 mA < 10 mA; không có R thì dòng không bị giới hạn bởi thiết kế; 5 mA lớn hơn nhiều điều kiện đo I<sub>OH<\/sub> = −60 µA nên bảng không bảo đảm V<sub>OH<\/sub> ở dòng đó (pull-up yếu; muốn biết chân cấp được bao nhiêu phải tra datasheet chip thật); 6 × 3 = 18 mA > 15 mA; 2,4 V nằm giữa 1,5 và 3,5 V của chip nhận; 3 × 4,55 = 13,65 mA ≤ 15 mA."}]);

makeQuiz("quiz5","score5",[{"q": "LED đỏ có VF = 2,0 V (giả định) nối tích cực mức thấp từ +5 V, chân có VOL = 0,45 V. Cần dòng 5 mA. Điện trở tính được là bao nhiêu?", "o": ["600 Ω", "1 000 Ω", "400 Ω", "510 Ω"], "a": 3, "e": "R = (5 − 2,0 − 0,45) ÷ 5 mA = 2,55 V ÷ 5 mA = 510 Ω. 600 Ω là quên trừ VOL; 1 000 Ω là chia cả 5 V cho dòng, quên LED và chân; 400 Ω là lấy VF chia cho dòng."}, {"q": "Datasheet (giả định) ghi VIL(max) = 0,9 V và VIH(min) = 1,9 V. Chip đọc điện áp vào 1,5 V là gì?", "o": ["Mức 1, vì lớn hơn VIL(max)", "Mức 0, vì nhỏ hơn VIH(min)", "Không xác định: có thể đọc 0 hoặc 1", "Mức 0, vì nhỏ hơn nửa nguồn (2,5 V)"], "a": 2, "e": "Chỉ dưới VIL(max) mới chắc chắn là 0 và chỉ trên VIH(min) mới chắc chắn là 1. 1,5 V nằm giữa hai ngưỡng nên datasheet không bảo đảm kết quả đọc. Mốc “nửa nguồn” không có trong datasheet."}, {"q": "Vì sao trên 8051 kiểu gốc, LED ở cổng P1 thường được nối tích cực mức thấp (sáng khi chân ở mức 0)?", "o": ["LED chỉ sáng khi catốt được nối thẳng xuống đất", "Ở mức 0 chân hút được dòng vài mA; ở mức 1 chân chỉ có pull-up yếu, cấp được dòng rất nhỏ", "Lệnh CLR chạy nhanh hơn lệnh SETB", "Mức 0 luôn tiết kiệm điện hơn mức 1 ở mọi mạch"], "a": 1, "e": "Cổng P1–P3 của 8051 có transistor kéo xuống mạnh nhưng chỉ có pull-up yếu khi ra mức 1. CLR P1.0 (C2H 90H) và SETB P1.0 (D2H 90H) cùng mất 1 chu kỳ máy; LED sáng khi có dòng thuận, không phụ thuộc nối catốt xuống đất."}, {"q": "Tám LED tích cực mức thấp nối P1.0…P1.7. Sau lệnh MOV P1,#0FEH, bao nhiêu LED sáng?", "o": ["7 LED (trừ P1.0)", "0 LED", "1 LED (ở P1.0)", "8 LED"], "a": 2, "e": "0FEH = 1111 1110B: chỉ bit 0 bằng 0, nên chỉ chân P1.0 ở mức thấp và chỉ LED đó sáng. “7 LED” là đọc như LED tích cực mức cao."}, {"q": "Tám LED cùng sáng trên một cổng, mỗi LED 4,55 mA. Giới hạn (giả định): 10 mA mỗi chân, 15 mA mỗi cổng. Kết luận nào đúng?", "o": ["Vượt: tổng 36,4 mA > 15 mA, phải giảm dòng mỗi LED hoặc dùng tầng đệm", "Đạt: mỗi chân 4,55 mA < 10 mA", "Đạt: chỉ cần xét giới hạn từng chân", "Vượt: phải tăng nguồn lên để giảm dòng"], "a": 0, "e": "8 × 4,55 = 36,4 mA, lớn hơn giới hạn 15 mA của cả cổng dù từng chân vẫn dưới 10 mA. Datasheet thường có giới hạn theo chân, theo cổng và theo cả chip; phải kiểm đủ."}]);

